draw:
var pad = 34;
var Lx = W - 2 * pad;
var midY = H * 0.45;
var mu = p.mu / 1000;
var v = Math.sqrt(p.tension / mu);
var f = p.n * v / (2 * p.L);
var A = H * 0.2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.faint;
ctx.fillRect(pad - 8, midY - 34, 8, 68);
ctx.fillRect(W - pad, midY - 34, 8, 68);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(pad, midY); ctx.lineTo(W - pad, midY); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.faint;
for (var s = -1; s <= 1; s += 2) {
  ctx.beginPath();
  for (var m = 0; m <= 240; m++) {
    var xe = pad + Lx * m / 240;
    var ye = midY - s * A * Math.sin(p.n * Math.PI * (xe - pad) / Lx);
    if (m === 0) { ctx.moveTo(xe, ye); } else { ctx.lineTo(xe, ye); }
  }
  ctx.stroke();
}

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x = pad + Lx * i / 240;
  var y = midY - A * Math.sin(p.n * Math.PI * (x - pad) / Lx) * Math.cos(2 * Math.PI * 1.2 * t);
  if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
for (var nd = 0; nd <= p.n; nd++) {
  var xn = pad + Lx * nd / p.n;
  ctx.beginPath(); ctx.arc(xn, midY, 3.5, 0, 6.2832); ctx.fill();
}

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
var yArrow = midY + A + 26;
ctx.beginPath();
ctx.moveTo(pad, yArrow); ctx.lineTo(pad + Lx / p.n, yArrow);
ctx.moveTo(pad, yArrow - 4); ctx.lineTo(pad, yArrow + 4);
ctx.moveTo(pad + Lx / p.n, yArrow - 4); ctx.lineTo(pad + Lx / p.n, yArrow + 4);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("half a wavelength", pad + 6, yArrow + 16);
ctx.fillText("fixed end", pad - 8, midY - 42);
ctx.fillText("fixed end", W - pad - 48, midY - 42);

out.note = "v = " + v.toFixed(1) + " m/s, wavelength = " + (2 * p.L / p.n).toFixed(3) + " m, f" + p.n + " = " + f.toFixed(1) + " Hz (fundamental " + (v / (2 * p.L)).toFixed(1) + " Hz)";
